SELECT 
FROM manga_ai_provider_config
WHERE id = #{configId}
  AND owner_user_id = #{ownerUserId}

SELECT COUNT(*)
FROM manga_ai_provider_config
WHERE owner_user_id = #{ownerUserId}
  AND name = #{name}

  AND id != #{excludedConfigId}

mapper.update:
UPDATE manga_ai_provider_config
SET default_config = FALSE,
    updated_by = #{actor}
WHERE owner_user_id = #{ownerUserId}
  AND default_config = TRUE

UPDATE manga_ai_provider_config
SET default_config = TRUE,
    enabled = TRUE,
    updated_by = #{actor}
WHERE id = #{configId}
  AND owner_user_id = #{ownerUserId}
